// Original classroom writing. Official sources are linked as evidence, not copied lesson text or art.
const freeze=x=>{if(x&&typeof x==='object'){for(const v of Object.values(x))freeze(v);Object.freeze(x);}return x;};
const option=(id,label,reply)=>({id,label,reply});
const source=(id,maker,type,date,purpose,url,locator,supports,limits)=>({id,maker,type,date,purpose,url,locator,supports,limits});
const q=(id,page,prompt,context,fields,hint,example,match,different,backcheck,errors=[])=>({id,page,prompt,context,fields:fields.map(([id,label,n,unit])=>({id,label,answer:{n,d:1},unit})),unitChoices:[{id:'m',label:'meters (m)'},{id:'cm',label:'centimeters (cm)'}],hintId:`hint-${id}`,exampleId:`example-${id}`,match,different,backcheck,errors,hint,example});
export function createRiverSource(serial=1){
 const s={version:1,id:`river-source-${serial}`,title:'Room for the River',story:'The librarian has made a new book from official records. Open any page: read the history, compare changes, reshape an invented rectangle, or keep a note for Willowbank.',labels:{history:'History · Netherlands',geometry:'Classroom geometry · invented numbers',story:'Story · Willowbank'},pages:['Read the record','Compare the measures','Same area, changing shape','Lent: distance and trade-offs','A note for the meeting'],
 passages:{history:[
 {id:'history-short',label:'Short',text:'High water flooded unprotected villages in Limburg in 1993 and 1995. In Gelderland in 1995, about 250,000 people were evacuated as a precaution because dikes might fail. The Room for the River program began in 2006 and was formally completed in early 2019. This is a new summary of official records, not an eyewitness account.'},
 {id:'history-medium',label:'Medium',text:'High water flooded unprotected Limburg villages in 1993 and 1995. In Gelderland in 1995, about 250,000 people were evacuated because of feared dike failures. The Room for the River program ran from 2006 to early 2019. It made more room for water at 34 locations, alongside dike work. Measures included moving dikes inland, making side channels and lowering floodplain land. A side channel can help water pass through; room-making is not only about holding water still.'},
 {id:'history-long',label:'Long',text:'High water flooded unprotected Limburg villages in 1993 and 1995. In Gelderland in 1995, about 250,000 people were evacuated as a precaution because of feared dike failures. Room for the River ran from 2006 to its formal completion in early 2019, at 34 locations. Rijkswaterstaat reports a total program cost of about €2.3 billion. Work on the Rhine branches, including the IJssel, Waal, Lower Rhine and Lek, combined room-making with dike protection. Meuse Works is a separate program. Side channels and lower floodplains can help convey water as well as provide space. Some farmland kept agricultural uses under changed conditions. Agency records explain the program, but cannot speak for every household or farmer who had to adapt.'}],
 lent:[{id:'lent-short',label:'Short',text:'At Lent on the Waal, a dike was moved about 350 meters inland and a side channel was made for high water. A Rijkswaterstaat retrospective says about 50 homes were demolished. Households had to move. These records do not tell us what every resident thought.'},
 {id:'lent-longer',label:'Longer',text:'A ministry brochure describes moving Lent’s dike about 350 meters inland and making a side channel for high-water discharge. Its picture was a planned visualization, not a measured map. A later Rijkswaterstaat transcript says about 50 homes were demolished and households moved. An older alternatives table counted homes and businesses together for a proposal; that is a different claim. In 2022, Nijmegen decided against additional homes on Veur Lent and for a city park with facilities. Existing buildings remain. A planning decision does not show that every later piece of work is finished, and official records cannot replace residents’ own accounts.'}]},
 sources:[
 source('program','Rijkswaterstaat','Official program explainer','Accessed October 26, 2026','Explain the national program and its scope.','https://www.rijkswaterstaat.nl/en/projects/iconic-structures/room-for-the-river','Programme (2006–2019)','Flooding in unprotected Limburg villages; precautionary evacuation in Gelderland; 2006–early 2019 program, 34 locations and reported total cost of €2.3 billion.','An agency summary is evidence of what the agency reports. It does not supply every resident’s account or predict every future flood.'),
 source('evacuation','Rijkswaterstaat','Official retrospective','January 2025','Remember the 1995 high-water emergency.','https://www.rijkswaterstaat.nl/en/news/archive/2025/01/thirty-years-later-the-1995-high-water-evacuation-remains-unforgettable','1995 evacuation retrospective','Precautionary evacuation during the 1995 high water.','A retrospective is written later. It does not make every area’s experience the same or establish how long every household was away.'),
 source('brochure','Dutch Ministry of Infrastructure and the Environment','Government program brochure','March 2014; accessed October 26, 2026','Describe projects and planned changes.','https://zoek.officielebekendmakingen.nl/blg-307544.pdf','PDF page 11, project 14; publication date in the closing colophon','A dike relocation of about 350 meters inland at Lent and a side channel for high-water discharge.','Its illustration is a planned visualization and its dates are an old schedule, not measured outcomes. No picture from it is reproduced here.'),
 source('homes','Rijkswaterstaat','Retrospective podcast transcript','Accessed October 26, 2026','Explain the program through a later discussion.','https://www.rijkswaterstaat.nl/water/waterbeheer/bescherming-tegen-het-water/maatregelen-om-overstromingen-te-voorkomen/ruimte-voor-de-rivieren','Transcript at 09:59','The retrospective reports about 50 Lent homes demolished and households moving.','The agency’s later account cannot establish each resident’s feelings. A proposed homes-and-businesses count is not the same as actual demolished homes.'),
 source('park','Municipality of Nijmegen','Municipal project record','2022 decision; page accessed October 26, 2026','Explain decisions and plans for Veur Lent and Hoge Bongerd.','https://www.nijmegen.nl/bouwprojecten/plannen-veur-lent-en-hoge-bongerd/','Stadspeiling 2022','The 2022 decision against additional homes on Veur Lent and for a city park with facilities; existing buildings remain.','A decision and later plans do not prove all proposed works are finished. Hoge Bongerd is a distinct site.'),
 source('design','Dutch government','Parliamentary answer','June 22, 2011','Answer questions about the selected design.','https://zoek.officielebekendmakingen.nl/kst-30080-54.html','Question 6; PDF page 3','An adult source note: the answer compared a 34 cm design result with a 27 cm requirement.','This is a design comparison, not an observed result for every flood or a safety guarantee. It is not a numeric task in this book.')],
 glossary:[{id:'dike',term:'Dike',text:'A long raised bank or barrier built to protect land from high water.'},{id:'floodplain',term:'Floodplain',text:'Low land beside a river that can flood when the water is high.'},{id:'sidechannel',term:'Side channel',text:'An additional route beside the main river through which water can pass under the project’s conditions.'},{id:'source',term:'Source',text:'Something we use to find out: for example, a report, photograph, interview or record. Ask who made it, when and why.'},{id:'account',term:'Account',text:'A description from a particular person or organization. Two accounts can tell us different things about the same event.'},{id:'prediction',term:'Design prediction',text:'A result expected from a design and its assumptions. It is different from a measurement made when an event happens.'}],
 timeline:[{id:'high-1993',year:1993,text:'High water; unprotected Limburg villages flooded.'},{id:'high-1995',year:1995,text:'High water and precautionary evacuation in Gelderland; Limburg villages also flooded.'},{id:'begin-2006',year:2006,text:'Room for the River program begins.'},{id:'complete-2019',year:2019,text:'Formal program completion in early 2019.'}],
 historyTask:{id:'history-order',prompt:'Put these dated cards in order, then compare with the visible timeline.',match:'This order agrees with the timeline: 1993, 1995, 2006, 2019. The dates on the cards stay available as support.',different:'Compare each card’s date with the timeline: 1993 comes before 1995, then 2006, then 2019. The timeline stays available while you move the cards.'},
 categories:[{id:'protection',label:'Dike protection'},{id:'room',label:'More room'}],sortTask:{id:'measure-sort',prompt:'Sort the main change described on each card.'},
 measures:[
 {id:'raise',title:'Raise a dike',text:'Make the top higher, adding height to the barrier.',fit:'protection',replies:{protection:'Raising changes the height of a protective barrier. It does not by itself move the dike inland.',room:'The described change is a higher barrier. There may be other work nearby, but this card does not add space beside the river.'}},
 {id:'strengthen',title:'Strengthen a dike',text:'Make the barrier more able to resist failure. This does not necessarily make its top higher.',fit:'protection',replies:{protection:'Strengthening changes how well the barrier resists failure. Strength and height are different.',room:'The card changes the barrier’s strength, not the space available for water beside it.'}},
 {id:'move',title:'Move a dike inland',text:'Place a dike farther from the river, opening more space on the river side.',fit:'room',replies:{protection:'There is still a protective dike. The main change described here is its position, which opens space.',room:'Moving the dike inland gives water more room on the river side. A real project still needs suitable dike protection.'}},
 {id:'channel',title:'Dig a side channel',text:'Make an additional route through which water can pass under the project’s conditions.',fit:'room',replies:{protection:'A side channel is an added water route, rather than a stronger or higher barrier.',room:'The added route gives water more room to pass. It is not only a container for still water.'}},
 {id:'lower',title:'Lower floodplain land',text:'Lower some land beside the river so high water has more space to pass over it.',fit:'room',replies:{protection:'This card changes land beside the river, rather than the barrier’s height or strength.',room:'Lower land can give high water more space to pass. Land-use effects depend on the particular project.'}},
 {id:'flood',title:'Allow a specified area to flood in high water',text:'Change protection or land use so high water can enter a chosen area. Some farming may continue under different conditions.',fit:'room',replies:{protection:'The described change deliberately makes a selected area available to high water. It is not simply a stronger barrier.',room:'This makes an area available to high water. It does not mean every farm stops operating or that every place uses the same arrangement.'}}],
 analogy:{measures:['raise','move','channel'],plans:[{id:'wall',label:'A wall',text:'A fictional wall beside Willowbank’s water.'},{id:'meadow',label:'A low wet meadow',text:'A fictional meadow with space for water.'},{id:'combination',label:'A combination',text:'A fictional idea with a barrier and some open space.'}],replies:{
 raise:{wall:'Both use a barrier. Raising a real dike involves ground, materials and forces that a simple story wall does not describe.',meadow:'Both could be discussed when planning for water. A raised barrier blocks water at an edge; the meadow offers space, so their main changes differ.',combination:'The combination has a barrier, like a raised dike. It also includes open space, which raising alone does not supply.'},
 move:{wall:'Both may include a barrier. Moving a dike changes where the barrier stands; the wall idea alone says nothing about moving it.',meadow:'Both can make space available beside water. Moving a dike also puts a protective boundary in a new place; a meadow alone does not describe that boundary.',combination:'Both bring a barrier and room into the discussion. We do not have Willowbank measurements or a design showing they would work in the same way.'},
 channel:{wall:'Both are possible things to compare in a water plan. A channel provides another route for water; a wall is a barrier.',meadow:'Both can provide space for water. A channel is a route for water to pass; a low meadow is not automatically such a route.',combination:'A channel could be part of a larger combination. This fictional combination has no designed channel or evidence that it would work like Lent.'}}},
 scale:{metersPerCentimeter:50},
 geometry:{mode:'rectangle',area:{n:2000,d:1},minWidth:100,maxWidth:1000,step:50,initialWidth:400,tile:{rows:3,columns:4},labels:{width:'Width',otherSide:'Other side',area:'Area',unit:'m',areaUnit:'m²',limit:'This rectangle has invented numbers. It cannot predict a real river’s water level, speed, discharge or safe dike design.',drawing:'Horizontal and vertical drawing scales differ so you can see the short side. This is a rectangle diagram, not a map or a physical river diagram.'}},
 tasks:[
 q('rectangle-height',2,'Find the missing side.','An invented rectangle has area 2000 m² and width 250 m.',[['other','Other side',8,'m']],'Area is width × other side. Divide the area by the known width.','Different example: an invented rectangle of area 100 m² and width 20 m has other side 100 ÷ 20 = 5 m.','8 m fits: 250 × 8 = 2000. Multiplication checks the division.','Divide 2000 by the given width of 250. The answer is a length in meters.','250 × 8 = 2000 m²',[{fieldId:'other',value:{n:500000,d:1},reply:'2000 × 250 multiplies the area by the width. To find a missing side, divide area by width.'},{fieldId:'other',value:{n:1750,d:1},reply:'2000 − 250 subtracts unlike quantities. Area divided by width gives the missing length.'}]),
 q('rectangle-extended',2,'Change the width, then find the other side.','Invented area: 2000 m². Start with width 250 m and add 150 m.\nFirst: new width = 250 + 150.\nThen: other side = 2000 ÷ new width.',[['width','New width',400,'m'],['other','Other side',5,'m']],'This takes two operations: add to find the new width, then divide to find the other side.','Different example: for area 100 m², a width of 15 m extended by 5 m becomes 20 m. The other side is 100 ÷ 20 = 5 m.','The new width is 400 m and the other side is 5 m: 400 × 5 = 2000.','Keep both steps: 250 + 150 gives the new width; divide 2000 by that new width.','400 × 5 = 2000 m²',[{fieldId:'width',value:{n:100,d:1},reply:'250 − 150 makes the width smaller. Here the instruction adds 150 to 250.'},{fieldId:'other',value:{n:8,d:1},reply:'8 m fits the old width of 250 m. Use the new width after adding 150 m.'}]),
 q('rectangle-width',2,'Find the width from the area and other side.','An invented rectangle has area 2000 m² and other side 4 m.',[['width','Width',500,'m']],'Undo width × 4 = 2000 by dividing the area by 4.','Different example: area 100 m² and one side 20 m gives a missing side of 100 ÷ 20 = 5 m.','500 m fits: 500 × 4 = 2000.','Divide area by the side you know. The missing width is in meters.','500 × 4 = 2000 m²',[{fieldId:'width',value:{n:8000,d:1},reply:'2000 × 4 makes a larger product. Division undoes multiplication when finding a missing side.'},{fieldId:'width',value:{n:1996,d:1},reply:'2000 − 4 does not undo width × 4. Divide the area by 4.'}]),
 q('scale-drawing',3,'How long is the distance on the hypothetical paper drawing?','The real documented setback is about 350 m. On this invented classroom scale, 1 cm represents 50 m.',[['distance','Drawing distance',7,'cm']],'Find how many groups of 50 meters fit into 350 meters. Each group is 1 centimeter on the hypothetical paper drawing.','Different example: at this classroom scale, 100 m is 100 ÷ 50 = 2 cm on the drawing.','7 cm fits the classroom scale: 350 ÷ 50 = 7. This is a drawing distance.','Divide the real distance by the meters represented by one drawing centimeter. Choose centimeters.','7 cm on the hypothetical paper drawing represents 350 m.',[{fieldId:'distance',value:{n:17500,d:1},reply:'350 × 50 goes in the other direction. To change real meters into drawing centimeters, divide by 50.'}]),
 q('scale-real',3,'What real distance does the drawing length represent?','On the same invented classroom scale, 1 cm represents 50 m. The practice drawing length is 7 cm.',[['distance','Represented real distance',350,'m']],'Each drawing centimeter represents 50 meters. There are seven such groups.','Different example: 2 cm at this classroom scale represents 2 × 50 = 100 m.','350 m fits: 7 × 50 = 350. This is the represented real distance.','Multiply the drawing centimeters by 50 meters per centimeter. Choose meters.','7 × 50 = 350 m.',[{fieldId:'distance',value:{n:7,d:50},reply:'7 ÷ 50 divides in the wrong direction here. Each of the 7 drawing centimeters represents 50 meters.'}])],
 discussions:[
 {id:'source-kind',page:0,prompt:'Who made this source, and what kind of source is it?',sourceIds:['program'],options:[option('agency','An agency explaining its program','Rijkswaterstaat made this official explainer. It is useful for what the agency reports, and is not a diary from the 1995 evacuation.'),option('date','An account published after the events','Yes, this page looks back on events. Its later date matters: it is not a record written by an evacuee during the emergency.'),option('purpose','A source written to explain public work','Its purpose helps us understand its selection of facts. We can still ask which experiences it leaves out.')]},
 {id:'source-support',page:0,prompt:'What can this source help establish?',sourceIds:['brochure'],options:[option('distance','The described dike setback','The brochure describes about 350 meters inland. Its planned picture is not a measured map.'),option('plan','What the ministry planned to do','A project brochure can explain a plan. Its old schedule cannot by itself prove when all later work finished.'),option('limits','Something to check against later records','A later completion record could answer a different question from an earlier plan. They should not be treated as the same evidence.')]},
 {id:'source-voice',page:0,prompt:'Whose account would you still want?',sourceIds:['homes'],options:[option('resident','A resident who moved','A resident’s interview could tell us about that person’s experience. The agency transcript does not supply all residents’ voices.'),option('farmer','A farmer whose conditions changed','A farmer’s account could explain local land use and decisions. We cannot infer that every farmer stopped farming.'),option('meeting','A record of a public meeting','A meeting record could show questions and disagreements. It would still not contain every private experience.')]},
 {id:'model-limits',page:2,prompt:'What can this rectangle tell us, and what remains outside it?',sourceIds:[],options:[option('identity','The area stays fixed in this rectangle','Yes. Width × other side stays equal to the invented area. That identity alone is not a claim about river flow.'),option('speed','It does not tell us how fast water moves','The model supplies lengths and area, with no water-speed measurements or flow assumptions.'),option('ground','It leaves out the shape and material of real ground','Yes. A rectangle does not describe a riverbed, soil, roughness, structures or connections.'),option('safety','It cannot set a safe dike design','Yes. The rectangle’s arithmetic cannot establish a safe water level or an engineering design.')]},
 ...[
 ['household','A displaced household','A household may have benefited from the wider project’s intended protection. The record does not tell us what that household valued most.','Losing a home and having to move is a documented cost. We do not know every household’s experience.','The project could have benefits while requiring a household to move. Both does not mean the benefits cancelled the loss.'],
 ['risk','Someone whose risk the project was designed to reduce','Reduced flood risk was a project aim. This card does not prove the risk at every person’s address or what they felt.','They might also have faced disruption or public costs. This card supplies no individual account establishing those costs.','A protection project can have gains and costs together. We would need local evidence to describe this person’s balance.'],
 ['farmer','A farmer whose land-use conditions changed','Some agricultural use continued under changed arrangements. A particular farmer’s gain would need their own account and project records.','Changed flooding or land-use conditions can be a cost. It is too broad to say all farms moved or all farming ended.','A farmer might face costs alongside other changes. We need project-specific evidence, not an invented statement about acceptance.'],
 ['visitor','A park visitor','The area offers recreation, and Nijmegen made a later park decision. A visitor’s enjoyment does not erase relocation costs.','A visitor may face limits on access or changes to familiar places. This card does not document a particular visitor’s loss.','Recreation can be a gain while changes also have costs. We cannot speak for every visitor.'],
 ['taxpayer','A taxpayer','Public flood-risk work can be a public benefit. The total program cost alone does not show each taxpayer’s personal gain.','Rijkswaterstaat reports about €2.3 billion in total program costs. That is a public cost, not a personal bill given on this card.','Public spending and intended public benefits can both matter. Their balance requires evidence and judgment, not a correctness mark.']
 ].map(([id,prompt,gain,give,both])=>({id:`perspective-${id}`,page:3,prompt,sourceIds:['program','homes','park'],options:[option('gain','Gain',gain),option('give','Give up',give),option('both','Both',both)]})),
 {id:'missing-voice',page:3,prompt:'Which further source would help you hear or check another account?',sourceIds:['homes'],options:[option('resident','A resident interview','Look for an interview with someone who moved. Ask when it was recorded and whose experience it describes.'),option('farmer','A farmer’s account','Look for an account of changed land use from a farmer, together with the relevant project conditions.'),option('downstream','A downstream record','A downstream record could help examine effects elsewhere. Check what was measured, when and where.'),option('meeting','A meeting record','Minutes or a recording can show public questions and official responses. People absent from the meeting may still have missing voices.')]}],
 parts:[{id:'idea',title:'One idea that could transfer',options:[{id:'room',text:'Making room for water is an idea to investigate in Willowbank, not a plan chosen for the town.'},{id:'identity',text:'A fixed-area rectangle can change its side lengths. That mathematical identity does not predict a river’s flood level.'},{id:'sources',text:'We can compare what official records establish with the accounts they leave out.'}]},{id:'difference',title:'One relevant difference',options:[{id:'place',text:'Willowbank is fictional. We have not given its measurements, land conditions or a real flood design.'},{id:'model',text:'Our rectangle uses invented numbers. The Lent setback is a documented distance from a different place.'},{id:'evidence',text:'A historical precedent describes an actual program; it cannot by itself recommend the same measures for a different town.'}]},{id:'cost',title:'One cost or unheard voice',options:[{id:'households',text:'About 50 Lent homes were demolished, according to the agency retrospective. I would want residents’ own accounts of moving.'},{id:'farms',text:'Some land-use conditions changed. I would want a farmer’s account rather than assume all farming stopped.'},{id:'public',text:'Public costs and intended benefits both matter. I would ask whose experience is still absent from our sources.'}]}],
 closing:'You have kept a note to think with. We can return to its ideas, differences and missing voices. The note does not settle Willowbank’s plan.',help:{},display:{}};
 for(const t of s.tasks){s.help[t.hintId]={title:'A hint',text:t.hint,facts:[]};s.help[t.exampleId]={title:'A different example',text:t.example,facts:[]};delete t.hint;delete t.example;}
 for(const x of s.sources)s.help[`source-${x.id}`]={title:`Source: ${x.maker}`,text:`${x.maker}. ${x.type}. ${x.date}. Purpose: ${x.purpose} Supports: ${x.supports} Limits: ${x.limits}`,facts:[]};
 for(const x of s.glossary)s.help[`glossary-${x.id}`]={title:x.term,text:x.text,facts:[]};
 for(const x of s.discussions)for(const o of x.options)s.help[`discussion-${x.id}-${o.id}`]={title:x.prompt,text:o.reply,facts:[]};
 for(const m of s.analogy.measures)for(const p of s.analogy.plans)s.help[`analogy-${m}-${p.id}`]={title:'A likeness and a difference',text:s.analogy.replies[m][p.id],facts:[]};
 for(const [section,ps] of Object.entries(s.passages))for(const p of ps){s.display[p.id]={title:`${section}: ${p.label}`,text:p.text,facts:[]};s.help[`audio-${p.id}`]={title:`Read ${p.label}`,text:p.text,facts:[]};}
 for(let i=0;i<s.pages.length;i++)s.display[`page-${i}`]={title:s.pages[i],text:i===0?'The dated timeline is available.':i===1?'The six described measures are available.':i===2?'Cover a rectangle with unit squares, without gaps or overlaps. The number of rows times the number of columns gives its area in square units. For a rectangle, width × other side = area. Division finds a missing side. Our larger rectangle uses invented lengths and area: changing its width changes the other side while its area stays fixed. A fraction means division; a decimal marked approximate is not the exact value.':i===3?'The classroom scale is invented: 1 centimeter on a hypothetical paper drawing represents 50 meters, so it is 1:5000 after converting to the same unit. To go from real meters to drawing centimeters, divide by 50. To go back, multiply the drawing centimeters by 50. The Lent distance comes from a historical source; this practice scale does not make a full map.':'The note prompts and ready-made words are available.',facts:[]};
 return freeze(s);
}
